            if d:IsA("TextLabel") and d.Visible and d.Text ~= "" then out[#out + 1] = d.Text end
        end
    end
    return out
end
function F.slipId()
    for _, t in ipairs(F.slip()) do
        local id = t:match("^#(%d+)")
        if id then return tonumber(id) end
    end
    return nil
end
function F.hint()
    for _, t in ipairs(F.slip()) do
        if t:sub(1, 3) == "\226\134\146" then return t end
    end
    return "-"
end
function F.recover()
    S.task = __T["Finding your order"]
    M.inv("GetPackingState")
    task.wait(0.2)
    if F.pkg or F.active then return end
    if M.num("BasketCount") > 0 then
        local t = M.tag("Ablagetisch")
        if t then F.at(t, "DepositProducts", 6, true) end
        task.wait(0.4)
        if F.active then LOG("recovered order", F.active.Id) return end
    end
    local id = F.slipId()
    local st, tray = Workspace:FindFirstChild("ScoopStation"), M.tag("ScoopTray")
    if st and tray then
        local res = F.at(st, "StartScoop", 7)
        if type(res) == "table" and res.Ok and res.Token then
            M.inv("FinishScoop", res.Token, F.trayPos(tray, #res.Farben, res.Farben))
            task.wait(0.4)
            if F.active then LOG("recovered from scoop", F.active.Id) return end
        end
    end
    for _, k in ipairs(CollectionService:GetTagged("TablettKugel")) do
        if k:GetAttribute("OrderId") == id and k:GetAttribute("Besitzer") == lp.UserId and not k:GetAttribute("Sortiert") then
            local a = M.inv("SelectMarble", k)
            if type(a) == "table" and a.Ok then M.inv("ConfirmColor", k:GetAttribute("Category")) end
            task.wait(0.4)
            if F.active then LOG("recovered from tray", F.active.Id) return end
            break
        end
    end
    local slip = F.slip()
    for i, t in ipairs(slip) do
        local a, b = tostring(slip[i + 1] or ""):match("^(%d+)/(%d+)$")
        if a and tonumber(a) < tonumber(b) then
            for cat, info in pairs(D.Items.Categories or {}) do
                if info.Display == t then
                    for c2, entries in pairs(F.buildIndex()) do
                        if c2 == cat or gcall(D.Items.Passt, c2, cat) then
                            for _, e in ipairs(entries) do
                                if e.part.Parent and F.spot(e.part, 7) then
                                    F.at(e.part, "PickProduct", 7, false, e.part)
                                    task.wait(0.4)
                                    if F.active then LOG("recovered from pick", F.active.Id) return end
                                    break
                                end
                            end
                        end
                    end
                end
            end
        end
    end
    LOG("open order from slip", tostring(id), F.hint())
    if id and on("f_abandon") and os.clock() >= (F.abandonAt or 0) then
        F.abandonAt = os.clock() + 15
        local r = M.inv("AbandonOrder", id)
        LOG("abandon reply", tostring(r))
        if r == true then
            F.skip[id] = true
            S.abandoned += 1
            notify(__T["Restarted your open order"])
        end
        task.wait(0.6)
    else
        S.task = __T["Finish your open order"]
        task.wait(2)
    end
end
function F.trayPos(tray, n, farben)
    local pos, y = {}, tray.Size.Y / 2 + 0.3
    if type(farben) ~= "table" then
        for i = 1, n do
            pos[i] = (tray.CFrame * CFrame.new(((i % 3) - 1) * 0.5, y, (math.floor((i - 1) / 3) % 3 - 1) * 0.5)).Position
        end
        return pos
    end
    local groups, order = {}, {}
    for i, c in ipairs(farben) do
        local k = tostring(c)
        if not groups[k] then groups[k] = {} order[#order + 1] = k end
        table.insert(groups[k], i)
    end
    for g, k in ipairs(order) do
        local cx, cz = -1.6 + ((g - 1) % 5) * 0.8, -1.1 + (math.floor((g - 1) / 5) % 4) * 0.73
        for j, idx in ipairs(groups[k]) do
            local dx, dz = ((j - 1) % 3) * 0.26, math.floor((j - 1) / 3) * 0.26
            pos[idx] = (tray.CFrame * CFrame.new(cx + dx, y, cz + dz)).Position
        end
    end
    return pos
end
function F.fail(key)
    F.fails[key] = (F.fails[key] or 0) + 1
    if F.fails[key] >= 8 then
        F.fails = {}
        local o = F.active
        LOG("stuck", key, o and o.Id, F.hint())
        if o and on("f_abandon") then
            if M.inv("AbandonOrder", o.Id) == true then
                S.abandoned += 1
                F.skip[o.Id] = true
            end
            F.tok = nil
        end
        task.wait(1)
    else
        task.wait(0.4)
    end
end
function F.buildIndex()
    if F.index then return F.index end
    S.task = __T["Reading shelves"]
    local idx, n = {}, 0
    local moebel = Workspace:FindFirstChild("Moebel")
    local vitrine = moebel and moebel:FindFirstChild("MiniVitrine")
    for _, f in ipairs({ Workspace:FindFirstChild("RegalProdukte"), Workspace:FindFirstChild("AblageProdukte"), Workspace:FindFirstChild("SquishyTisch"), Workspace:FindFirstChild("SpecialTisch"), vitrine or false }) do
        if f then
            for _, d in ipairs(f:GetDescendants()) do
                if d:IsA("BasePart") then
                    local id, cat = d:GetAttribute("ItemId"), d:GetAttribute("Category")
                    if id and cat then
                        idx[cat] = idx[cat] or {}
                        table.insert(idx[cat], { part = d, id = id })
                    end
                end
                n += 1
                if n % 2500 == 0 then task.wait() end
            end
        end
    end
    F.index = idx
    return idx
end
function F.itemInfo(id)
    F.infoCache = F.infoCache or {}
    local v = F.infoCache[id]
    if v == nil then
        v = gcall(D.Items.GetItem, id) or false
        F.infoCache[id] = v
    end
    return v or nil
end
function F.rarityBonus(it)
    local pay = D.Cfg.Economy.RarityPayout
    local base = D.Cfg.Economy.BasePayoutPerItem
    return base * ((pay[it.Rarity] or 1) - 1)
end
function F.listFor(o, cat)
    if F.listOrder ~= o.Id then F.listOrder, F.lists = o.Id, {} end
    if F.lists[cat] then return F.lists[cat] end
    local out, seen = {}, {}
    for c2, entries in pairs(F.buildIndex()) do
        if c2 == cat or gcall(D.Items.Passt, c2, cat) then
            for _, e in ipairs(entries) do
                if not seen[e.id] and not F.bad[e.part] then
                    seen[e.id] = true
                    local it = F.itemInfo(e.id)
                    local skip = (not it) or gcall(D.Items.IstZugabe, e.id) or (D.Items.NurUpgrade and D.Items.NurUpgrade[e.id])
                    if not skip and gcall(D.Gen.Mag, o, e.id) ~= false then
                        local score = F.rarityBonus(it)
                        if type(o.Wunsch) == "table" and #o.Wunsch > 0 then
                            for _, c in ipairs(it.Farben or {}) do
                                if table.find(o.Wunsch, c) then score = score + 60 break end
                            end
                        end
                        out[#out + 1] = { part = e.part, id = e.id, score = score }
                    end
                end
            end
        end
    end
    table.sort(out, function(a, b) return a.score > b.score end)
    F.lists[cat] = out
    return out
end
function F.accept()
    S.task = __T["Getting an order"]
    local pc = M.tag("BestellPC")
    if not pc then F.fail("nopc") return end
    local board = M.inv("BestellBrett")
    if type(board) ~= "table" then F.fail("board") return end
    local best
    local wantBig = val("f_size", "Biggest") == "Biggest"
    local maxP = val("f_maxp", 15)
    for _, o in ipairs(board) do
        if o.Status == "Open" and not F.skip[o.Id] and (o.Portions or 1) <= maxP then
            if not best or (wantBig and o.BaseValue > best.BaseValue) or (not wantBig and o.BaseValue < best.BaseValue) then best = o end
        end
    end
    if not best then
        if F.slipId() then F.recover() return end
        if on("f_reroll") and #board > 0 and (F.rerolls or 0) < 3 then
            local big
            for _, o in ipairs(board) do
                if o.Status == "Open" and (not big or (o.Portions or 1) > (big.Portions or 1)) then big = o end
            end
            if big then
                F.rerolls = (F.rerolls or 0) + 1
                S.rerolled = (S.rerolled or 0) + 1
                F.at(pc, "RejectOrder", 6, false, big.Id)
                task.wait(0.35)
                return
            end
        end
        for _, o in ipairs(board) do
            if o.Status == "Open" and (not best or (o.Portions or 1) < (best.Portions or 1)) then best = o end
        end
        if not best then
            S.task = __T["Waiting for orders"]
            task.wait(2)
            return
        end
    end
    if on("f_reroll") and wantBig and (F.rerolls or 0) < 3 then
        local worst
        for _, o in ipairs(board) do
            if o.Status == "Open" and o.BaseValue < val("f_minv", 800) and (not worst or o.BaseValue < worst.BaseValue) then worst = o end
        end
        if worst then
            S.task = __T["Finding better orders"]
            F.rerolls = (F.rerolls or 0) + 1
            local rr = F.at(pc, "RejectOrder", 6, false, worst.Id)
            S.rerolled = (S.rerolled or 0) + 1
            LOG("rerolled", worst.Id, worst.BaseValue, tostring(rr))
            task.wait(0.35)
            return
        end
    end
    F.rerolls = 0
    local r = F.at(pc, "AcceptOrder", 6, false, best.Id)
    if r == true then
        F.fails, F.bad = {}, {}
        task.wait(0.15)
    elseif F.slipId() then
        F.recover()
    else
        F.fail("accept")
    end
end
function F.scoop(o)
    S.task = string.format(__T["Scooping %d/%d"], o.ScoopsDone or 0, o.Portions or 1)
    local st = Workspace:FindFirstChild("ScoopStation")
    local tray = M.tag("ScoopTray")
    if not (st and tray) then F.fail("nostation") return end
    local res = F.at(st, "StartScoop", 7)
    if type(res) ~= "table" then F.fail("scoop") return end
    local tok, n = res.Token, res.Farben and #res.Farben or 6
    if not res.Ok then
        if F.tok and tostring(res.Reason):find("already", 1, true) then tok, n = F.tok, F.tokN or 6 else LOG("scoop", tostring(res.Reason)) F.fail("scoop") return end
    end
    F.tok, F.tokN = tok, n
    local fin = M.inv("FinishScoop", tok, F.trayPos(tray, n, res.Farben))
    if type(fin) == "table" and fin.Ok then F.fails = {} F.tok = nil task.wait(0.1) else LOG("finish", type(fin) == "table" and tostring(fin.Reason) or "nil") F.fail("finish") end
end
function F.sort(o)
    S.task = __T["Sorting"]
    local any, done = false, {}
    for _, k in ipairs(CollectionService:GetTagged("TablettKugel")) do
        if not done[k] and k:GetAttribute("OrderId") == o.Id and k:GetAttribute("Besitzer") == lp.UserId and not k:GetAttribute("Sortiert") then
            any = true
            local cat = k:GetAttribute("Category")
            local a = M.inv("SelectMarble", k)
            if type(a) == "table" and a.Ok then
                for _, b in ipairs(a.Gruppe or {}) do done[b] = true end
                S.sortCalls = (S.sortCalls or 0) + 1
                S.sortBalls = (S.sortBalls or 0) + (tonumber(a.Anzahl) or 1)
                local c = M.inv("ConfirmColor", cat)
                if not (type(c) == "table" and c.Ok) then LOG("confirm", cat, type(c) == "table" and tostring(c.Reason) or "nil") end
            end
            if not RUNNING or not on("f_auto") then return end
        end
    end
    if not any then F.fail("nomarbles") else F.fails = {} end
end
function F.openBoxes()
    for slot, it in ipairs(table.clone(F.handList or {})) do
        if D.Items.Mystery and D.Items.Mystery[it.Id] then
            local r = M.inv("OpenSurprise", it.Id, slot)
            LOG("open box", it.Id, slot, type(r) == "table" and tostring(r.Ok) .. " " .. tostring(r.Reason) or tostring(r))
        end
    end
end
function F.dropExtras()
    for _, it in ipairs(table.clone(F.handList or {})) do
        local r = M.inv("DropProduct", it.Id)
        LOG("drop", it.Id, type(r) == "table" and tostring(r.Ok) or tostring(r))
    end
end
function F.deposit()
    S.task = __T["Dropping items"]
    local t = M.tag("Ablagetisch")
    if not t then F.fail("notable") return end
    local r = F.at(t, "DepositProducts", 6, true)
    if type(r) == "table" and r.Ok then
        if (r.Zu or 0) > 0 then
            F.openBoxes()
            F.fail("boxes")
        elseif (r.Behalten or 0) > 0 and (r.Anzahl or 0) == 0 then
            F.dropExtras()
            F.fail("extras")
        else
            F.fails = {}
        end
    else
        LOG("deposit", type(r) == "table" and tostring(r.Reason) or "nil")
        if type(r) == "table" and tostring(r.Reason):find("already enough", 1, true) then F.dropExtras() end
        F.fail("deposit")
    end
end
function F.bestOf(list)
    for _, e in ipairs(list) do
        if not F.bad[e.part] and e.part.Parent then return e end
    end
end
function F.pick(o)
    local free = F.cap - F.hand
    if free <= 0 then F.deposit() return end
    local first
    for _, ln in ipairs(o.Lines or {}) do
        if (ln.Amount or 0) - math.max(ln.Collected or 0, ln.Delivered or 0) > 0 then first = ln break end
    end
    if not first then return end
    S.task = string.format(__T["Picking %s"], tostring(first.Category))
    local anchor
    for _, e in ipairs(F.listFor(o, first.Category)) do
        if not F.bad[e.part] and e.part.Parent then
            if F.spot(e.part, 7) then anchor = e break end
            F.bad[e.part] = true
        end
    end
    if not anchor then
        LOG("no item for", first.Category)
        F.fails.noitem = 7
        F.fail("noitem")
        return
    end
    local stand = F.spot(anchor.part, 7)
    local batch = {}
    for _, ln in ipairs(o.Lines or {}) do
        local need = math.min((ln.Amount or 0) - math.max(ln.Collected or 0, ln.Delivered or 0), free - #batch)
        if need > 0 then
            local list = F.listFor(o, ln.Category)
            local top = F.bestOf(list)
            for _, e in ipairs(list) do
                if not F.bad[e.part] and e.part.Parent and top and e.score >= top.score - 30 and (e.part.Position - stand).Magnitude <= F.REACH then
                    for _ = 1, need do batch[#batch + 1] = e end
                    break
                end
            end
        end
    end
    if #batch == 0 then batch[1] = anchor end
    local root = M.root()
    if not root or (root.Position - stand).Magnitude > 1.5 then
        M.go(stand)
        S.tps = (S.tps or 0) + 1
        task.wait(0.25)
    end
    local left, okN, full, v0 = #batch, 0, false, F.ver or 0
    for _, e in ipairs(batch) do
        task.spawn(function()
            local r = M.inv("PickProduct", e.part)
            if type(r) == "table" and r.Ok then
                okN += 1
            elseif type(r) == "table" and r.Voll then
                full = true
            elseif type(r) == "table" and tostring(r.Reason):lower():find("closer", 1, true) then
                S.closer = (S.closer or 0) + 1
            else
                LOG("pick", e.id, type(r) == "table" and tostring(r.Reason) or "nil")
                F.bad[e.part] = true
            end
            left -= 1
        end)
    end
    local t0 = os.clock()
    while left > 0 and RUNNING and os.clock() - t0 < 9 do task.wait(0.02) end
    S.picks += okN
    local waitAt = os.clock()
    while okN > 0 and (F.ver or 0) < v0 + okN and RUNNING and os.clock() - waitAt < 0.8 do task.wait(0.02) end
    if full then F.deposit() return end
    if okN > 0 then F.fails = {} task.wait(0.08) else task.wait(0.12) F.fail("pick") end
end
function F.wantFreebie(o)
    if not on("f_freebie") then return false end
    F.fb = F.fb or {}
    local cap = D.Cfg.Packing.MiniGeschenkeProPaket or 2
    return (o.Freebies or 0) < cap and (F.fb[o.Id] or 0) < cap + 3
end
function F.freebie(o)
    F.fb[o.Id] = (F.fb[o.Id] or 0) + 1
    if F.hand >= F.cap then F.deposit() return end
    S.task = __T["Adding freebies"]
    for _, e in ipairs(F.buildIndex().MiniGeschenk or {}) do
        if not F.bad[e.part] and e.part.Parent then
            local r, why = F.at(e.part, "PickProduct", 7, false, e.part)
            if type(r) == "table" and r.Ok then
                S.picks += 1
                task.wait(0.05)
                return
            elseif type(r) == "table" and r.Voll then
                F.deposit()
                return
            elseif why == "nospot" or type(r) == "table" then
                LOG("freebie", e.id, why or tostring(r.Reason))
                F.bad[e.part] = true
                return
            end
        end
    end
end
function F.fit(items, box)
    local tol, maxH, aufl = D.Pack.Toleranz, D.Pack.MaxHoehe, D.Pack.Auflage
    local function over(a, b)
        local dx = math.min(a.X2, b.X2) - math.max(a.X1, b.X1)
        local dy = math.min(a.Y2, b.Y2) - math.max(a.Y1, b.Y1)
        return (dx <= 0 or dy <= 0) and 0 or dx * dy
    end
    local function hidden(x1, y1, w1, h1, x2, y2, w2, h2)
        local dx = math.min(x1 + w1, x2 + w2) - math.max(x1, x2)
        local dy = math.min(y1 + h1, y2 + h2) - math.max(y1, y2)
        if dx <= 0 or dy <= 0 then return false end
        return dx * dy > math.min(w1 * h1, w2 * h2) * 0.5
    end
    local function steps(limit)
        local out = {}
        for i = 0, limit, 2 do out[#out + 1] = i end
        if out[#out] ~= limit then out[#out + 1] = limit end
        return out
    end
    local list = table.clone(items)
    table.sort(list, function(a, b) return a.A > b.A end)
    local placed, tick = {}, os.clock()
    for _, v in ipairs(list) do
        local bestBase, found = math.huge, nil
        for _, shape in ipairs({ v.L, v.S }) do
            if shape.Hoehe <= maxH then
                for _, rot in ipairs({ false, true }) do
                    local w = rot and shape.H or shape.W
                    local h = rot and shape.W or shape.H
                    if box.W >= w and box.H >= h then
                        local kx, ky = math.floor(w * 0.2), math.floor(h * 0.2)
                        local area = (w - 2 * kx) * (h - 2 * ky)
                        local xs = steps(box.W - w)
                        for _, y in ipairs(steps(box.H - h)) do
                            for _, x in ipairs(xs) do
                                if os.clock() - tick > 0.005 then
                                    task.wait()
                                    tick = os.clock()
                                end
                                local kern = { X1 = x + kx, Y1 = y + ky, X2 = x + w - kx, Y2 = y + h - ky }
                                local base = 0
                                for _, p in ipairs(placed) do
                                    if base < p.Top and over(kern, p.Kern) > 0 then base = p.Top end
                                end
                                if bestBase > base and base + shape.Hoehe <= maxH + 0.01 then
                                    local valid = true
                                    if base > 0 then
                                        local support = 0
                                        for _, p in ipairs(placed) do
                                            if p.Top >= base - tol then support = support + over(kern, p.Kern) end
                                        end
                                        valid = support >= area * aufl - 0.001
                                    end
                                    if valid then
                                        for _, p in ipairs(placed) do
                                            if base < p.Top - tol and p.Basis < base + shape.Hoehe - tol and hidden(x, y, w, h, p.X, p.Y, p.W, p.H) then
                                                valid = false
                                                break
                                            end
                                        end
                                    end
                                    if valid then
                                        found = { X = x, Y = y, W = w, H = h, Basis = base, Top = base + shape.Hoehe, Kern = kern, Standing = shape == v.S, Rot = rot }
                                        bestBase = base
                                    end
                                end
                            end
                            if bestBase == 0 then break end
                        end
                        if bestBase == 0 then break end
                    end
                end
                if bestBase == 0 then break end
            end
        end
        if not found then return false, placed end
        found.D = v
        placed[#placed + 1] = found
    end
    return true, placed
end
function F.layout(ps)
    local box = ps.Boxen and ps.Boxen[1]
    for _, b in ipairs(ps.Boxen or {}) do
        if b.Name == ps.Vorschlag then box = b end
    end
    if not box then return nil end
    local list = {}
    for _, it in ipairs(ps.Items or {}) do
        local d = gcall(D.Pack.Daten, it.Id, it.Kategorie)
        if not d then return nil end
        list[#list + 1] = { A = d.A, L = d.L, S = d.S, Id = it.Id }
    end
    local ok, pl = F.fit(list, box)
    if not ok then return nil, box end
    local out = {}
    for i, p in ipairs(pl) do
        local d, s, r = p.D, p.Standing, p.Rot
        out[i] = { Id = d.Id, X = p.X, Y = p.Y, R = r, S = s, L = i, F = on("f_extras") and not F.noExtras and F.fragile(d.Id) or false }
    end
    return out, box
end
function F.fragile(id)
    for _, pre in ipairs(D.Cfg.Packing.Zerbrechlich or {}) do
        if id:sub(1, #pre) == pre then return true end
    end
    return false
end
function F.extras()
    if not on("f_extras") or F.noExtras then return {} end
    local p = D.Cfg.Packing
    return {
        Tuch = p.Seidenpapier and p.Seidenpapier[1] and p.Seidenpapier[1].Id or nil,
        Fuell = p.Fuellmaterial and p.Fuellmaterial[1] and p.Fuellmaterial[1].Id or nil,
        Karte = true,
        Tape = "rosa",
        KartePlatz = { X = 0.5, Y = 0.5, R = -6 },
    }
end
function F.bigger(name)
    local list = table.clone(D.Cfg.Packing.Boxen)
    table.sort(list, function(a, b) return a.W * a.H < b.W * b.H end)
    for i, b in ipairs(list) do
        if b.Name == name then return list[i + 1] and list[i + 1].Name end
    end
    return nil
end
function F.boxName(o)
    for _, b in ipairs(D.Cfg.Packing.Boxen) do
        if b.Anzeige == o.Karton or b.Name == o.Karton then return b.Name end
    end
    return nil
end
function F.pack(o)
    S.task = __T["Packing"]
    local name = F.boxOver[o.Id] or F.boxName(o)
    if not name then F.fail("nobox") return end
    local spot = M.tag("PackPlatz")
    if not spot then F.fail("nopack") return end
    local ps = F.at(spot, "PackStart", 6, true)
    if type(ps) == "table" and not ps.Ok and tostring(ps.Reason):lower():find("box", 1, true) then
        for _, f in ipairs(CollectionService:GetTagged("KartonRegal")) do
            if f:GetAttribute("Box") == name then
                local k = F.at(f, "KartonNehmen", 7, false, name, nil)
                if not (type(k) == "table" and k.Ok) then LOG("box", type(k) == "table" and tostring(k.Reason) or "nil") end
            end
        end
        ps = F.at(spot, "PackStart", 6, true)
    end
    if not (type(ps) == "table" and ps.Ok) then LOG("packstart", type(ps) == "table" and tostring(ps.Reason) or "nil") F.fail("packstart") return end
    local items, box = F.layout(ps)
    if not items then
        local nextBox = F.bigger(box and box.Name or name)
        LOG("layout failed", box and box.Name, "trying", tostring(nextBox))
        M.inv("PackVerlassen")
        if nextBox then
            F.boxOver[o.Id] = nextBox
            for _, sh in ipairs(CollectionService:GetTagged("KartonRegal")) do
                if sh:GetAttribute("Box") == nextBox then F.at(sh, "KartonNehmen", 7, false, nextBox, nil) end
            end
        end
        F.fail("layout")
        return
    end
    local r = M.inv("PackFertig", box.Name, items, F.extras())
    if type(r) == "table" and not r.Ok and on("f_extras") and not F.noExtras then
        LOG("extras refused", type(r) == "table" and tostring(r.Reason) or "nil")
        F.noExtras = true
        for _, it in ipairs(items) do it.F = false end
        r = M.inv("PackFertig", box.Name, items, {})
    end
    if type(r) == "table" and r.Ok then F.fails = {} LOG("packed stars", r.Stars) task.wait(0.15) else LOG("packfertig", type(r) == "table" and tostring(r.Reason) or "nil") F.fail("packfertig") end
end
function F.ship()
    local p = F.pkg
    S.task = __T["Shipping"]
    F.setupZones()
    local root = M.root()
    if F.packStand and root and (not p.Gedruckt or not p.Genommen) and (root.Position - F.packStand).Magnitude > 2 then
        M.go(F.packStand)
        S.tps = (S.tps or 0) + 1
        task.wait(0.25)
    end
    if not p.Gedruckt then
        local pr = M.inv("PrintLabel")
        if type(pr) == "table" and pr.Ok then
            task.wait(1.4)
        else
            LOG("print", type(pr) == "table" and tostring(pr.Reason) or "nil")
            F.fail("print")
        end
        return
    end
    if not p.Genommen then M.inv("TakeLabel") task.wait(0.15) return end
    if not p.Etikett then M.inv("AttachLabel") task.wait(0.15) return end
    if not p.Getragen then M.inv("TakePackage") task.wait(0.15) return end
    local door = M.tag("Abholplatz")
    if not door then F.fail("nodoor") return end
    local before = M.num("Money")
    local r = F.at(door, "ShipPackage", 8)
    if type(r) == "table" and r.Ok then
        S.done += 1
        S.earned += tonumber(r.Total) or 0
        local ab = r.Abrechnung or {}
        LOG("shipped", r.Total, "stars", r.Stars, "money", before, M.num("Money"), "tuch", ab.Tuch, "fuell", ab.Fuell, "folie", ab.Folie, "karte", ab.Karte, "geschenk", ab.Geschenk, "rarity", ab.RarityBonus, "tip", ab.Tip)
        F.pkg, F.active = nil, nil
        F.fails = {}
        task.wait(0.15)
    else
        LOG("ship", type(r) == "table" and tostring(r.Reason) or "nil")
        F.fail("ship")
    end
end
function F.step()
    if F.pkg then F.ship() return end
    local o = F.active
    if not o then F.accept() return end
    if (o.ScoopsDone or 0) < (o.Portions or 1) then F.scoop(o) return end
    if (o.ImTablett or 0) > 0 or o.Status == "Accepted" then F.sort(o) return end
    for _, ln in ipairs(o.Lines or {}) do
        if math.max(ln.Collected or 0, ln.Delivered or 0) < (ln.Amount or 0) then F.pick(o) return end
    end
    if F.wantFreebie(o) then F.freebie(o) return end
    if (o.InHand or 0) > 0 or F.hand > 0 then F.deposit() return end
    F.pack(o)
end
