local L = { at = 0 }
function L.stand(pos)
    local rp = RaycastParams.new()
    rp.FilterType = Enum.RaycastFilterType.Exclude
    rp.FilterDescendantsInstances = { lp.Character }
    local down = Workspace:Raycast(pos + Vector3.new(0, 8, 0), Vector3.new(0, -20, 0), rp)
    local lobby = Workspace:FindFirstChild("Lobby")
    if not down or down.Normal.Y < 0.8 or down.Instance:IsA("Seat") or down.Instance:IsA("VehicleSeat") or not lobby or not down.Instance:IsDescendantOf(lobby) then return nil end
    local stand = down.Position + Vector3.new(0, 3.2, 0)
    local op = OverlapParams.new()
    op.FilterType = Enum.RaycastFilterType.Exclude
    op.FilterDescendantsInstances = { lp.Character }
    for _, h in ipairs(Workspace:GetPartBoundsInBox(CFrame.new(stand + Vector3.new(0, 0.4, 0)), Vector3.new(6, 6, 6), op)) do
        if h:IsA("Seat") or h:IsA("VehicleSeat") then return nil end
    end
    for _, h in ipairs(Workspace:GetPartBoundsInBox(CFrame.new(stand + Vector3.new(0, 0.4, 0)), Vector3.new(3, 5, 3), op)) do
        if h.CanCollide then return nil end
    end
    return stand
end
function L.fountain()
    if L.tossed or not on("l_fountain") or not fireproximityprompt then return end
    local lobby = Workspace:FindFirstChild("Lobby")
    local deko = lobby and lobby:FindFirstChild("Deko")
    local b = deko and deko:FindFirstChild("Brunnen")
    if not b then L.tossed = true return end
    local prompt
    for _, d in ipairs(b:GetDescendants()) do
        if d:IsA("ProximityPrompt") then prompt = d break end
    end
    if not (prompt and prompt.Parent and prompt.Parent:IsA("BasePart")) then L.tossed = true return end
    local wp = prompt.Parent.Position
    for _, r in ipairs({ 4, 5, 6, 7 }) do
        for i = 0, 15 do
            local a = i / 16 * math.pi * 2
            local p = L.stand(Vector3.new(wp.X + math.cos(a) * r, wp.Y, wp.Z + math.sin(a) * r))
            if p then
                S.task = "Tossing a coin"
                M.go(p)
                task.wait(0.8)
                fireproximityprompt(prompt)
                L.tossed = true
                LOG("fountain tossed")
                task.wait(1)
                return
            end
        end
    end
    L.tossed = true
end
function L.enter()
    if not on("l_auto") or os.clock() < L.at then return end
    local group = M.attr("Gruppe")
    if group ~= nil then
        local st = Workspace.Lobby:FindFirstChild("Studios")
        st = st and st:FindFirstChild("Studio" .. tostring(group))
        if not st or st:GetAttribute("Anzahl") ~= 1 or st:GetAttribute("Modus") ~= 1 then
            S.task = __T["In a group, not starting"]
            L.at = os.clock() + 2
            return
        end
        L.readies = (L.readies or 0) + 1
        if L.readies > 4 then
            L.readies = 0
            L.at = os.clock() + 4
            local out = M.inv("GruppeAktion", "Verlassen")
            LOG("leave group", type(out) == "table" and tostring(out.Ok) or tostring(out))
            return
        end
        S.task = __T["Starting your shop"]
        L.at = os.clock() + 8
        local r = M.inv("GruppeAktion", "Bereit", true)
        LOG("ready", type(r) == "table" and tostring(r.Ok) .. " " .. tostring(r.Reason) or tostring(r))
        return
    end
    L.readies = 0
    local studios = Workspace.Lobby:FindFirstChild("Studios")
    local root, best, bd = M.root(), nil, nil
    if not studios or not root then return end
    for _, x in ipairs(studios:GetChildren()) do
        local f = x:FindFirstChild("Feld")
        local state = x:GetAttribute("Zustand")
        if f and state ~= "gruppe" and state ~= "laden" then
            local d = (f.Position - root.Position).Magnitude
            if not bd or d < bd then best, bd = f, d end
        end
    end
    if not best then
        S.task = __T["Waiting for a free pad"]
        L.at = os.clock() + 2
        return
    end
    local p = L.stand(best.Position)
    if not p then L.at = os.clock() + 2 return end
    S.task = __T["Going to a free pad"]
    M.go(p)
    L.at = os.clock() + 3
end
