task.spawn(function()
    local hist = {}
    while RUNNING do
        pcall(function()
            local now = os.clock()
            hist[#hist + 1] = { now, S.earned }
            while #hist > 2 and now - hist[1][1] > 120 do table.remove(hist, 1) end
            local dt = now - hist[1][1]
            local rate = dt > 10 and (S.earned - hist[1][2]) / dt * 60 or 0
            setText(UI.s1, string.format(__T["Coins %s · %s/min"], M.coins(M.num("Money")), M.coins(rate)))
            setText(UI.s2, string.format(__T["Shipped %d · Skipped %d"], S.done, S.abandoned))
            setText(UI.s3, __T["Doing: "] .. S.task)
            setText(UI.s4, now - (S.gmsgAt or 0) < 8 and S.gmsg or string.format(__T["Items picked %d"], S.picks))
        end)
        task.wait(0.5)
    end
end)
